(()=>{const select=document.querySelector('.language');if(!select)return;const originals=new WeakMap();const dict={Français:{'Tivione IPTV Plans':'Plans Tivione IPTV','Tivione IPTV Reseller Packages':'Forfaits revendeur Tivione IPTV','Apps & installation':'Applications et installation','Make your device ready':'Préparez votre appareil','Setup, player & streaming guides':'Guides d’installation, lecteur et streaming','Talk to the team':'Parlez à notre équipe','Explore plans':'Voir les forfaits','Explore reseller':'Voir les offres revendeur','Request this plan':'Demander ce forfait','Contact sales':'Contacter les ventes','Continue exploring':'Continuer à explorer','Choose the next step for your setup.':'Choisissez la prochaine étape pour votre installation.','Plans':'Forfaits','Apps':'Applications','Reseller':'Revendeur','Guides':'Guides','Blog':'Blog','Contact':'Contact','Home':'Accueil','Pricing':'Tarifs','Get Started':'Commencer','Server features':'Fonctionnalités du serveur','Everything included with reseller access':'Tout ce qui est inclus avec l’accès revendeur'},Español:{'Tivione IPTV Plans':'Planes Tivione IPTV','Tivione IPTV Reseller Packages':'Paquetes de revendedor Tivione IPTV','Apps & installation':'Apps e instalación','Make your device ready':'Prepara tu dispositivo','Setup, player & streaming guides':'Guías de instalación, reproductor y streaming','Talk to the team':'Habla con el equipo','Explore plans':'Ver planes','Explore reseller':'Ver revendedor','Request this plan':'Solicitar este plan','Contact sales':'Contactar ventas','Continue exploring':'Seguir explorando','Choose the next step for your setup.':'Elige el siguiente paso para tu configuración.','Plans':'Planes','Apps':'Aplicaciones','Reseller':'Revendedor','Guides':'Guías','Blog':'Blog','Contact':'Contacto','Home':'Inicio','Pricing':'Precios','Get Started':'Empezar','Server features':'Funciones del servidor','Everything included with reseller access':'Todo incluido con el acceso de revendedor'},العربية:{'Tivione IPTV Plans':'خطط Tivione IPTV','Tivione IPTV Reseller Packages':'باقات موزع Tivione IPTV','Apps & installation':'التطبيقات والتثبيت','Make your device ready':'جهّز جهازك','Setup, player & streaming guides':'أدلة الإعداد والمشغلات والبث','Talk to the team':'تواصل مع الفريق','Explore plans':'استعرض الخطط','Explore reseller':'استعرض الموزع','Request this plan':'اطلب هذه الخطة','Contact sales':'تواصل مع المبيعات','Continue exploring':'تابع الاستكشاف','Choose the next step for your setup.':'اختر الخطوة التالية لإعدادك.','Plans':'الخطط','Apps':'التطبيقات','Reseller':'موزع','Guides':'الأدلة','Blog':'المدونة','Contact':'اتصل بنا','Home':'الرئيسية','Pricing':'الأسعار','Get Started':'ابدأ الآن','Server features':'خصائص الخادم','Everything included with reseller access':'كل ما يتضمنه وصول الموزع'}};function apply(language){const map=dict[language]||{};document.documentElement.lang=language==='العربية'?'ar':language==='Français'?'fr':language==='Español'?'es':'en';document.documentElement.dir=language==='العربية'?'rtl':'ltr';const walk=document.createTreeWalker(document.querySelector('main'),NodeFilter.SHOW_TEXT);let n;while(n=walk.nextNode()){if(!n.nodeValue.trim())continue;let base=originals.get(n)||n.nodeValue;originals.set(n,base);n.nodeValue=map[base.trim()]?base.replace(base.trim(),map[base.trim()]):base}document.querySelectorAll('.nav a,.footer a').forEach(a=>{const base=a.dataset.i18n||(a.dataset.i18n=a.textContent.trim());if(map[base])a.textContent=map[base];else if(language==='English')a.textContent=base})}const saved=localStorage.getItem('tivione-language')||'English';select.value=saved;apply(saved);select.onchange=e=>{localStorage.setItem('tivione-language',e.target.value);apply(e.target.value)}})();
